-- Pinjam initial PostgreSQL schema.
-- Applied by scripts/db-migrate.mjs inside a transaction; recorded in schema_migrations.
-- Identity columns are GENERATED BY DEFAULT so the SQLite import can keep existing ids.

-- Needed for the exclusion constraint that stops overlapping reservations (trusted extension).
CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE TABLE users (
  id                   integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email                text NOT NULL CHECK (email = lower(email)),
  password_hash        text NOT NULL,
  full_name            text NOT NULL CHECK (char_length(full_name) BETWEEN 2 AND 80),
  nim                  text NOT NULL CHECK (char_length(nim) BETWEEN 5 AND 20),
  major                text,
  phone                text,
  avatar_key           text,
  student_id_card_key  text,
  -- Verification is not automated yet: these stay NULL until a verifier sets them.
  email_verified_at    timestamptz,
  student_verified_at  timestamptz,
  rules_accepted_at    timestamptz,
  notify_reminders     boolean NOT NULL DEFAULT true,
  theme                text NOT NULL DEFAULT 'light' CHECK (theme IN ('light', 'dark')),
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT users_email_key UNIQUE (email),
  CONSTRAINT users_nim_key UNIQUE (nim)
);

CREATE TABLE sessions (
  id          text PRIMARY KEY,                -- SHA-256 of the cookie token
  user_id     integer NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  expires_at  timestamptz NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX sessions_user_idx ON sessions (user_id);
CREATE INDEX sessions_expires_idx ON sessions (expires_at);

-- Uploaded images live in the database so they persist on serverless hosts.
CREATE TABLE files (
  key         text PRIMARY KEY,                -- e.g. item/<uuid>.jpg
  owner_id    integer NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  kind        text NOT NULL CHECK (kind IN ('item', 'avatar', 'idcard')),
  mime        text NOT NULL CHECK (mime IN ('image/jpeg', 'image/png', 'image/webp')),
  size        integer NOT NULL CHECK (size > 0),
  data        bytea NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX files_owner_idx ON files (owner_id);

CREATE TABLE categories (
  id    integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  slug  text NOT NULL UNIQUE,
  name  text NOT NULL UNIQUE,
  sort  integer NOT NULL DEFAULT 0
);

CREATE TABLE items (
  id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  owner_id       integer NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  category_id    integer NOT NULL REFERENCES categories (id),
  name           text NOT NULL CHECK (char_length(name) BETWEEN 2 AND 80),
  description    text NOT NULL DEFAULT '',
  condition      text NOT NULL CHECK (condition IN ('new', 'good', 'fair')),
  price_per_day  integer NOT NULL DEFAULT 0 CHECK (price_per_day >= 0),
  max_days       integer NOT NULL CHECK (max_days BETWEEN 1 AND 30),
  pickup_point   text NOT NULL CHECK (char_length(pickup_point) BETWEEN 2 AND 60),
  is_available   boolean NOT NULL DEFAULT true,
  deleted_at     timestamptz,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX items_owner_idx ON items (owner_id);
CREATE INDEX items_category_idx ON items (category_id);
CREATE INDEX items_listed_idx ON items (created_at DESC) WHERE deleted_at IS NULL AND is_available;

CREATE TABLE item_images (
  id        integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  item_id   integer NOT NULL REFERENCES items (id) ON DELETE CASCADE,
  file_key  text NOT NULL REFERENCES files (key) ON DELETE CASCADE,
  position  integer NOT NULL DEFAULT 0
);
CREATE INDEX item_images_item_idx ON item_images (item_id);

-- A loan is a borrowing request and, once approved, the transaction itself.
CREATE TABLE loans (
  id                integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  item_id           integer NOT NULL REFERENCES items (id),
  borrower_id       integer NOT NULL REFERENCES users (id),
  lender_id         integer NOT NULL REFERENCES users (id),
  start_date        date NOT NULL,                -- pickup date
  end_date          date NOT NULL,                -- return-by date
  days              integer NOT NULL CHECK (days >= 1),
  price_per_day     integer NOT NULL CHECK (price_per_day >= 0),
  fee_total         integer NOT NULL CHECK (fee_total >= 0),
  payment_method    text NOT NULL CHECK (payment_method IN ('none', 'cash', 'transfer')),
  fee_received_at   timestamptz,
  note              text,
  status            text NOT NULL CHECK (status IN (
                      'pending', 'approved', 'rejected', 'ready_for_pickup',
                      'borrowed', 'return_pending', 'completed', 'cancelled')),
  return_condition  text CHECK (return_condition IN ('same', 'damaged', 'missing_parts')),
  reminder_sent_at  timestamptz,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  approved_at       timestamptz,
  picked_up_at      timestamptz,
  returned_at       timestamptz,
  completed_at      timestamptz,
  CONSTRAINT loans_dates_check CHECK (end_date >= start_date),
  CONSTRAINT loans_not_self_check CHECK (borrower_id <> lender_id),
  -- No two approved/active loans of the same item may overlap (half-open: same-day handover is fine).
  CONSTRAINT loans_no_overlap EXCLUDE USING gist (
    item_id WITH =,
    daterange(start_date, end_date, '[)') WITH &&
  ) WHERE (status IN ('approved', 'ready_for_pickup', 'borrowed', 'return_pending'))
);
CREATE INDEX loans_item_status_idx ON loans (item_id, status);
CREATE INDEX loans_borrower_idx ON loans (borrower_id, status);
CREATE INDEX loans_lender_idx ON loans (lender_id, status);
-- A student can have only one open request/loan per item.
CREATE UNIQUE INDEX loans_one_open_per_borrower ON loans (item_id, borrower_id)
  WHERE status IN ('pending', 'approved', 'ready_for_pickup', 'borrowed', 'return_pending');

-- Audit trail of every status change.
CREATE TABLE loan_events (
  id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  loan_id      integer NOT NULL REFERENCES loans (id) ON DELETE CASCADE,
  actor_id     integer REFERENCES users (id),
  from_status  text,
  to_status    text NOT NULL,
  note         text,
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX loan_events_loan_idx ON loan_events (loan_id);

CREATE TABLE conversations (
  id               integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  item_id          integer NOT NULL REFERENCES items (id),
  borrower_id      integer NOT NULL REFERENCES users (id),
  lender_id        integer NOT NULL REFERENCES users (id),
  created_at       timestamptz NOT NULL DEFAULT now(),
  last_message_at  timestamptz,
  CONSTRAINT conversations_item_borrower_key UNIQUE (item_id, borrower_id),
  CONSTRAINT conversations_not_self_check CHECK (borrower_id <> lender_id)
);
CREATE INDEX conversations_lender_idx ON conversations (lender_id);

CREATE TABLE messages (
  id               integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  conversation_id  integer NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
  sender_id        integer NOT NULL REFERENCES users (id),
  body             text NOT NULL CHECK (char_length(body) BETWEEN 1 AND 1000),
  created_at       timestamptz NOT NULL DEFAULT now(),
  read_at          timestamptz
);
CREATE INDEX messages_conversation_idx ON messages (conversation_id, id);

CREATE TABLE reviews (
  id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  loan_id      integer NOT NULL REFERENCES loans (id),
  reviewer_id  integer NOT NULL REFERENCES users (id),
  reviewee_id  integer NOT NULL REFERENCES users (id),
  rating       integer NOT NULL CHECK (rating BETWEEN 1 AND 5),
  comment      text,
  created_at   timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT reviews_loan_reviewer_key UNIQUE (loan_id, reviewer_id),
  CONSTRAINT reviews_not_self_check CHECK (reviewer_id <> reviewee_id)
);
CREATE INDEX reviews_reviewee_idx ON reviews (reviewee_id);

CREATE TABLE notifications (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id     integer NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  type        text NOT NULL,
  title       text NOT NULL,
  body        text NOT NULL DEFAULT '',
  link        text,
  read_at     timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX notifications_user_idx ON notifications (user_id, id DESC);
CREATE INDEX notifications_unread_idx ON notifications (user_id) WHERE read_at IS NULL;

CREATE TABLE reports (
  id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  reporter_id  integer NOT NULL REFERENCES users (id),
  item_id      integer NOT NULL REFERENCES items (id),
  reason       text NOT NULL CHECK (reason IN (
                 'misleading', 'prohibited', 'not_owner', 'unsafe', 'spam', 'other')),
  details      text,
  status       text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'reviewed', 'dismissed')),
  created_at   timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT reports_reporter_item_key UNIQUE (reporter_id, item_id)
);

